package io.github.chronicle.core.offering.temporary;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.*;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.*;

class TemporaryOfferingStoreTest {
    @TempDir Path directory;
    private TemporaryOfferingClaim claim(){var terms=new TemporaryOfferingTerms(6000,0,25,Map.of("levels","3"));return new TemporaryOfferingClaim(UUID.fromString("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"),UUID.fromString("11111111-1111-1111-1111-111111111111"),"quiet_below:network","quiet_below:cave_sight","station",10,6010,terms,TemporaryOfferingClaim.State.CLAIMED,null);}
    @Test void createsMarkerRoundTripsAndRetainsPriorBackup()throws Exception{Path file=directory.resolve("world/chronicle/temporary-offerings.json");TemporaryOfferingLedger saved;byte[] empty;try(var store=new TemporaryOfferingStore(file)){var initial=store.loadOrCreate();empty=Files.readAllBytes(file);saved=initial.add(0,claim());assertEquals(saved,store.save(saved,initial));store.verifyUnchanged();}assertArrayEquals(empty,Files.readAllBytes(file.resolveSibling("temporary-offerings.json.bak")));try(var store=new TemporaryOfferingStore(file)){assertEquals(saved,store.loadOrCreate());}}
    @Test void invalidOrExternallyChangedEvidenceIsNeverReplaced()throws Exception{Path file=directory.resolve("authority.json");try(var store=new TemporaryOfferingStore(file)){store.loadOrCreate();Files.writeString(file,"{invalid");assertThrows(Exception.class,store::verifyUnchanged);assertEquals("{invalid",Files.readString(file));}Path missing=directory.resolve("missing.json");try(var store=new TemporaryOfferingStore(missing)){store.loadOrCreate();}Files.delete(missing);try(var store=new TemporaryOfferingStore(missing)){assertThrows(Exception.class,store::loadOrCreate);}assertFalse(Files.exists(missing));}
    @Test void strictDecoderRejectsUnknownDuplicateAndNoncanonicalNumbers(){String valid=TemporaryOfferingStore.encode(TemporaryOfferingLedger.EMPTY);assertThrows(IllegalArgumentException.class,()->TemporaryOfferingStore.decode(valid.replaceFirst("\\{","{\"unknown\":true,")));assertThrows(IllegalArgumentException.class,()->TemporaryOfferingStore.decode(valid.replaceFirst("\"revision\"\\s*:\\s*0","\"revision\":0,\"revision\":1")));assertThrows(IllegalArgumentException.class,()->TemporaryOfferingStore.decode(valid.replaceFirst("\"revision\"\\s*:\\s*0","\"revision\":0.0")));}
    @Test void terminalArchiveRetainsExactRetriesBeyondOldLifetimeLimit()throws Exception{Path file=directory.resolve("repeat/temporary-offerings.json");try(var store=new TemporaryOfferingStore(file)){TemporaryOfferingLedger ledger=store.loadOrCreate();for(int i=0;i<129;i++){UUID id=new UUID(0,i+1);var instant=new TemporaryOfferingClaim(id,claim().player(),claim().source(),claim().offering(),"station",i,i,new TemporaryOfferingTerms(0,0,0,Map.of("sequence",Integer.toString(i))),TemporaryOfferingClaim.State.CLAIMED,null);TemporaryOfferingLedger added=ledger.add(ledger.revision(),instant);ledger=store.save(added,ledger);TemporaryOfferingLedger complete=ledger.transition(ledger.revision(),id,TemporaryOfferingClaim.State.CLAIMED,TemporaryOfferingClaim.State.COMPLETE,null);ledger=store.save(complete,ledger);if(ledger.claims().size()>=32)ledger=store.archiveTerminals(ledger,ignored->true);}ledger=store.archiveTerminals(ledger,ignored->true);assertTrue(ledger.claims().isEmpty());assertEquals(TemporaryOfferingClaim.State.COMPLETE,store.archived(new UUID(0,1)).orElseThrow().state());assertEquals("128",store.archived(new UUID(0,129)).orElseThrow().terms().evidence().get("sequence"));}}
    @Test void directSaveCannotSkipRewindOrResurrectArchivedClaim()throws Exception{Path file=directory.resolve("graph/temporary-offerings.json");try(var store=new TemporaryOfferingStore(file)){var empty=store.loadOrCreate();var claimed=empty.add(0,claim());store.save(claimed,empty);var skipped=new TemporaryOfferingLedger(claimed.revision()+1,List.of(claim().with(TemporaryOfferingClaim.State.EXPIRED,null)),Set.of());assertThrows(IllegalStateException.class,()->store.save(skipped,claimed));var complete=claimed.transition(claimed.revision(),claim().transaction(),TemporaryOfferingClaim.State.CLAIMED,TemporaryOfferingClaim.State.COMPLETE,null);store.save(complete,claimed);var rewind=new TemporaryOfferingLedger(complete.revision()+1,List.of(claim()),Set.of());assertThrows(IllegalStateException.class,()->store.save(rewind,complete));}}
}
